#!/usr/bin/env bash
set -euo pipefail
echo "Installing Agentic-universe sources into: $(pwd)"
if [[ ! -d .git ]]; then echo "ERROR: run inside ~/Agentic-universe"; exit 1; fi
python3 - <<'PY'
import base64, io, tarfile
payload = ""
raw = base64.b64decode(payload)
with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
    names = tf.getnames()
    tf.extractall(".")
print(f"Extracted {len(names)} paths")
PY
chmod +x run.sh scripts/*.sh 2>/dev/null || true
git add -A
git status --short | head -50
if git diff --cached --quiet; then echo "Nothing new to commit"; else git commit -m "Import Formi outcome-first agent loop controller"; fi
git branch -M main
git push -u origin main
echo
echo "OK — code is local and pushed to GitHub."
echo "Next: python3 -m pip install -r requirements.txt"

